    /**
     * Tests creating a new HardwareModule.
     *
     * @return    HardwareModule
     */
    public HardwareModule testCreate() throws Throwable {
    HardwareModule entity = null;

    LOGGER.info( "HardwareModuleTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a HardwareModule");

    StringBuilder msg = new StringBuilder( "-- Failed to create a HardwareModule" );

    try {
        entity = service.createHardwareModule( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getHardwareModuleId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a HardwareModule with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

