    /**
     * Tests getting all HardwareModules.
     *
     * @return    Collection
     */
    public List<HardwareModule> testGetAll() throws Throwable {
    LOGGER.info( "HardwareModuleTest:testGetAll() - Retrieving Collection of HardwareModules:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all HardwareModule : " );
    List<HardwareModule> collection  = null;

    try {
        // call the static get method on the HardwareModuleService
        collection = service.getAllHardwareModule();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            HardwareModule currEntity  = null;
            Iterator<HardwareModule> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getHardwareModuleId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

